"""
Easter Eggs
---
Cool little secret Easter Eggs.
Can serve as experimentation on how far you can push the browser.
It's also pretty fun
"""
import base64, lzma, io
import pygame
import time

rickroll = b""
def checkurl(url):
    url = url.lower()

    if "rickroll" in url:
        try:
            raw = lzma.decompress(base64.b64decode(rickroll))
            audio = io.BytesIO(raw)
            pygame.mixer.init()
            pygame.mixer.music.load(audio)
            pygame.mixer.music.play()
            while pygame.mixer.music.get_busy():
                time.sleep(0.1)
        except Exception as e:
            print(e)